function parseNpmRef(source) {
  const npm_part = source.slice(4)
  if (!npm_part) throw new Error(`Invalid npm reference: "${source}"`)
  let pkgName, version

  if (npm_part.startsWith('@')) {
    const slashIdx = npm_part.indexOf('/')
    if (slashIdx === -1) throw new Error(`Invalid npm reference: "${source}"`)
    const rest = npm_part.slice(slashIdx + 1)
    const atIdx = rest.indexOf('@')
    if (atIdx > 0) {
      pkgName = npm_part.slice(0, slashIdx + 1 + atIdx)
      version = rest.slice(atIdx + 1)
    } else {
      pkgName = npm_part
      version = 'latest'
    }
  } else {
    const atIdx = npm_part.lastIndexOf('@')
    if (atIdx > 0) {
      pkgName = npm_part.slice(0, atIdx)
      version = npm_part.slice(atIdx + 1)
    } else {
      pkgName = npm_part
      version = 'latest'
    }
  }

  return { pkgName, version }
}
